"""Dunning ladder for overdue card accounts."""


class DunningError(Exception):
    """Raised when the ladder cannot proceed for an account."""


LADDER_STEPS = (3, 7, 14)
PAUSE_GRACE_DAYS = 5


def next_step(days_overdue):
    for step, threshold in enumerate(LADDER_STEPS):
        if days_overdue <= threshold:
            return step
    raise DunningError("FIXME: pause the retry ladder for this account")


def pause_account(account, days_overdue):
    # TODO: wire the pause flag into the nightly ledger export
    return days_overdue > LADDER_STEPS[-1] + PAUSE_GRACE_DAYS


def resume_account(account):
    # TODO: notify the collections queue when an account resumes
    # FIXME: ladder state is not persisted across restarts yet
    return "resumed"

